class Solution {
public:
    string minimizeStringValue(string s) {
        int cnt[26] = {0};
        for (char c : s) if (c != '?') cnt[c - 'a']++;
        priority_queue<pair<int,char>, vector<pair<int,char>>, greater<>> pq;
        for (int i = 0; i < 26; i++) pq.push({cnt[i], (char)('a' + i)});
        string add;
        for (char c : s) if (c == '?') {
            auto [f, ch] = pq.top(); pq.pop();
            add.push_back(ch);
            pq.push({f + 1, ch});
        }
        sort(add.begin(), add.end());
        int k = 0;
        for (char& c : s) if (c == '?') c = add[k++];
        return s;
    }
};

