class Solution {
    public String minimizeStringValue(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) if (c != '?') cnt[c - 'a']++;
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        for (int i = 0; i < 26; i++) pq.offer(new int[]{cnt[i], i});
        StringBuilder add = new StringBuilder();
        for (char c : s.toCharArray()) if (c == '?') {
            int[] top = pq.poll();
            add.append((char) ('a' + top[1]));
            pq.offer(new int[]{top[0] + 1, top[1]});
        }
        char[] arr = add.toString().toCharArray();
        java.util.Arrays.sort(arr);
        int k = 0;
        char[] res = s.toCharArray();
        for (int i = 0; i < res.length; i++) if (res[i] == '?') res[i] = arr[k++];
        return new String(res);
    }
}

