var minimizeStringValue = function(s) {
    const cnt = Array(26).fill(0);
    for (const c of s) if (c !== '?') cnt[c.charCodeAt(0) - 97]++;
    const heap = [];
    for (let i = 0; i < 26; i++) heap.push([cnt[i], i]);
    const cmp = (a, b) => a[0] - b[0] || a[1] - b[1];
    heap.sort(cmp);
    const add = [];
    for (const c of s) if (c === '?') {
        const top = heap.shift();
        add.push(String.fromCharCode(97 + top[1]));
        top[0]++;
        let i = 0;
        while (i + 1 < heap.length && cmp(top, heap[i + 1]) > 0) { heap[i] = heap[i + 1]; i++; }
        heap[i] = top;
    }
    add.sort();
    let k = 0;
    return [...s].map(c => c === '?' ? add[k++] : c).join('');
};

