class Solution:
    def minimizeStringValue(self, s: str) -> str:
        cnt = [0] * 26
        for ch in s:
            if ch != '?':
                cnt[ord(ch) - 97] += 1
        order = sorted(range(26), key=lambda i: (cnt[i], i))
        q = s.count('?')
        add = []
        for rank, idx in enumerate(order):
            extra = q // 26 + (1 if rank < q % 26 else 0)
            add.extend(chr(97 + idx) * extra)
        add.sort()
        it = iter(add)
        return ''.join(next(it) if ch == '?' else ch for ch in s)

