        vector<int> order(26);
        iota(order.begin(), order.end(), 0);
        stable_sort(order.begin(), order.end(), [&](int a, int b) { return cnt[a] < cnt[b]; });
        int q = count(s.begin(), s.end(), '?');
        string add;
        for (int rank = 0; rank < 26; rank++) {
            int extra = q / 26 + (rank < q % 26 ? 1 : 0);
            add.append(extra, (char)('a' + order[rank]));
        }
        sort(add.begin(), add.end());
        int k = 0;
        for (char& c : s) if (c == '?') c = add[k++];
        return s;
    }
};

