class Solution {
    public String minimizeStringValue(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) if (c != '?') cnt[c - 'a']++;
        Integer[] order = new Integer[26];
        for (int i = 0; i < 26; i++) order[i] = i;
        java.util.Arrays.sort(order, (a, b) -> cnt[a] - cnt[b]);
        int q = 0;
        for (char c : s.toCharArray()) if (c == '?') q++;
        StringBuilder sb = new StringBuilder();
        for (int rank = 0; rank < 26; rank++) {
            int extra = q / 26 + (rank < q % 26 ? 1 : 0);
            for (int t = 0; t < extra; t++) sb.append((char) ('a' + order[rank]));
        }
        char[] add = sb.toString().toCharArray();
        java.util.Arrays.sort(add);
        int k = 0;
        char[] res = s.toCharArray();
        for (int i = 0; i < res.length; i++) if (res[i] == '?') res[i] = add[k++];
        return new String(res);
    }
}

